import psycopg2
import os
from flask import Flask, request, jsonify, g
from functools import wraps
import hashlib
import time
import re

app = Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'inventory')
DB_USER = os.environ.get('DB_USER', 'app_user')
DB_PASS = os.environ.get('DB_PASS', 'secret')

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(
            host=DB_HOST, dbname=DB_NAME,
            user=DB_USER, password=DB_PASS
        )
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def require_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        key = request.headers.get('X-API-Key')
        if not key or len(key) < 32:
            return jsonify({'error': 'unauthorized'}), 401
        # Verify key exists in allowed_keys table
        db = get_db()
        cur = db.cursor()
        cur.execute("SELECT 1 FROM allowed_keys WHERE key_hash = %s",
                    (hashlib.sha256(key.encode()).hexdigest(),))
        if not cur.fetchone():
            return jsonify({'error': 'invalid key'}), 403
        return f(*args, **kwargs)
    return decorated

def validate_warehouse_id(wid):
    """Warehouse IDs must be alphanumeric with optional hyphens"""
    if not re.match(r'^[A-Za-z0-9\-]{1,20}$', wid):
        return False
    return True

@app.route('/api/v2/inventory/search', methods=['GET'])
@require_api_key
def search_inventory():
    warehouse = request.args.get('warehouse', '')
    category = request.args.get('category', '')
    min_qty = request.args.get('min_qty', '0')
    sort_field = request.args.get('sort', 'item_name')

    if not validate_warehouse_id(warehouse):
        return jsonify({'error': 'invalid warehouse id'}), 400

    # Validate min_qty is numeric
    try:
        min_qty_int = int(min_qty)
        if min_qty_int < 0:
            min_qty_int = 0
    except ValueError:
        min_qty_int = 0

    # Build query with parameterized warehouse and min_qty
    # Sort field uses allowlist... but category is filtered differently
    allowed_sorts = ['item_name', 'quantity', 'last_updated', 'sku']
    if sort_field not in allowed_sorts:
        sort_field = 'item_name'

    # Category filter - uses LIKE for partial matching
    # Developer note: category comes from a controlled dropdown in the UI
    if category:
        category_clause = f"AND category ILIKE '%{category}%'"
    else:
        category_clause = ""

    query = f"""
        SELECT sku, item_name, category, quantity, warehouse_id, last_updated
        FROM inventory_items
        WHERE warehouse_id = %s
        AND quantity >= %s
        {category_clause}
        ORDER BY {sort_field}
        LIMIT 100
    """

    db = get_db()
    cur = db.cursor()
    cur.execute(query, (warehouse, min_qty_int))
    rows = cur.fetchall()

    results = []
    for row in rows:
        results.append({
            'sku': row[0],
            'item_name': row[1],
            'category': row[2],
            'quantity': row[3],
            'warehouse_id': row[4],
            'last_updated': row[5].isoformat() if row[5] else None
        })

    return jsonify({'results': results, 'count': len(results)})

@app.route('/api/v2/inventory/bulk_update', methods=['POST'])
@require_api_key
def bulk_update():
    """Bulk update quantities - uses parameterized queries throughout"""
    data = request.get_json()
    if not data or 'updates' not in data:
        return jsonify({'error': 'missing updates'}), 400

    db = get_db()
    cur = db.cursor()
    updated = 0

    for item in data['updates']:
        sku = item.get('sku', '')
        new_qty = item.get('quantity', 0)
        if not re.match(r'^[A-Z0-9\-]{5,15}$', sku):
            continue
        cur.execute(
            "UPDATE inventory_items SET quantity = %s, last_updated = NOW() WHERE sku = %s",
            (int(new_qty), sku)
        )
        updated += cur.rowcount

    db.commit()
    return jsonify({'updated': updated})

@app.route('/api/v2/inventory/stats', methods=['GET'])
@require_api_key
def inventory_stats():
    warehouse = request.args.get('warehouse', '')
    if not validate_warehouse_id(warehouse):
        return jsonify({'error': 'invalid warehouse id'}), 400

    db = get_db()
    cur = db.cursor()
    cur.execute("""
        SELECT category, COUNT(*), SUM(quantity)
        FROM inventory_items
        WHERE warehouse_id = %s
        GROUP BY category
    """, (warehouse,))

    stats = [{'category': r[0], 'items': r[1], 'total_qty': r[2]} for r in cur.fetchall()]
    return jsonify({'warehouse': warehouse, 'stats': stats})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
